 assert.equal(r.closedTuple,true);assert.equal(r.fixedCmd,true);assert.equal(r.fixedWorkingDirectory,true);assert.equal(r.fixedPowerShell,true);assert.equal(r.effectCapability,false);assert.equal(r.retainedHashCapsuleBound,true);assert.equal(r.defaultSourceInvocationInert,true);assert.deepEqual(r.acceptedCases,[true,false,false,false,false,false,false,false,false,false,false,false]);
 // Supplemental signed-log data only: one fixed public-buffer sample, with no
 // speed threshold, host identity or resource-acceptance interpretation.
