function publicJobHelloFraming(source){
 const cases=[['plain',['HELLO\n'],true],['crlf',['HELLO\r\n'],true],['one-bom',['\uFEFFHELLO\n'],true],['one-bom-split',['\uFEFFHE','LLO\r\n'],true],['double-bom',['\uFEFF\uFEFFHELLO\n'],false],['embedded-bom',['HE\uFEFFLLO\n'],false],['space',[' HELLO\n'],false],['bad-cr',['HELLO\r\r\n'],false],['extra',['HELLO\nEXTRA'],false],['wrong',['WRONG\n'],false]];const rows=[];
 for(const [id,chunks,expected]of cases){let data;const writes=[],spawns=[],timers=[];const child={pid:123,on:()=>{},stderr:{on:()=>{}},stdout:{setEncoding:()=>{},on:()=>{}}},processData={env:{},stdin:{setEncoding:()=>{},on:(name,fn)=>{assert.equal(name,'data');data=fn;}},stdout:{write:value=>writes.push(value)},exit:code=>{throw new Error('PUBLIC_EXIT_'+code);}};runInNewContext(source,{process:processData,require:name=>{assert.equal(name,'node:child_process');return {spawn:(...args)=>{spawns.push(args);return child;}};},setTimeout:(_fn,ms)=>{timers.push(ms);return {};}});assert.deepEqual(writes,['READY\n']);assert.deepEqual(timers,[8000]);assert.equal(spawns.length,0);let refused=false;try{for(const chunk of chunks)data(chunk);}catch(e){assert.equal(e.message,'PUBLIC_EXIT_76');refused=true;}const accepted=!refused&&spawns.length===1;rows.push({id,expected,accepted,spawnCount:spawns.length,pass:accepted===expected});if(accepted){assert.throws(()=>data('HELLO\n'),/^Error: PUBLIC_EXIT_76$/);assert.equal(spawns.length,1);}}
 return {profile:'goriq-public-job-hello-framing-v1',meaning:'SOURCE_EXTRACTED_PUBLIC_PARSER_DATA_NOT_ACTUAL_WINDOWS_JOB_CAUSE',pass:rows.every(row=>row.pass),rows,nativeAuthority:false,actualProcessesStarted:0};
}

